const steps = { validate, reserve, charge };

async function advance(env) {
  while (env.cursor < env.slip.length) {
    const fn = steps[env.slip[env.cursor]];   // whitelist lookup
    if (!fn) throw new Error(`unknown step ${env.slip[env.cursor]}`);
    env.body = await fn(env.body);
    env.cursor += 1;
  }
  return env.body;
}
